import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Container, Form, Button, Card, Alert } from 'react-bootstrap';

function ProfileForm({ onProfileCreated }) {
  const [formData, setFormData] = useState({
    nickname: '',
    age: '',
    gender: 'M', // 기본값 남성
    bio: '',
    interests: '',
    location: '',
  });
  
  const [profileId, setProfileId] = useState(null); // 🔑 수정할 프로필의 ID 저장
  const [error, setError] = useState('');

  // 1. 컴포넌트가 켜지자마자 "내 프로필 ID"를 알아냅니다.
  useEffect(() => {
    const fetchMyProfileId = async () => {
        const accessToken = localStorage.getItem('accessToken');
        if (!accessToken) return;

        try {
            const response = await axios.get(
                'http://127.0.0.1:8000/api/users/userprofile/me/',
                { headers: { 'Authorization': `Bearer ${accessToken}` } }
            );
            // 이미 가입할 때 만들어진 프로필의 ID를 가져옴
            setProfileId(response.data.id);
            console.log("기존 프로필 ID 확인:", response.data.id);
        } catch (err) {
            console.error("프로필 정보 가져오기 실패", err);
        }
    };
    fetchMyProfileId();
  }, []);


  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const accessToken = localStorage.getItem('accessToken');
    
    if (!accessToken) {
      alert("로그인이 필요합니다.");
      return;
    }
    
    // 프로필 ID를 아직 못 가져왔으면 잠시 대기
    if (!profileId) {
        alert("프로필 정보를 불러오는 중입니다. 잠시 후 다시 시도해주세요.");
        return;
    }

    try {
      // 🔑 핵심 수정: POST(생성)가 아니라 PATCH(수정)를 사용합니다!
      // URL 뒤에 profileId를 붙여서 "이 프로필을 수정해줘"라고 요청합니다.
      const url = `http://127.0.0.1:8000/api/users/userprofile/${profileId}/`;
      
      const response = await axios.patch(url, formData, {
        headers: {
          'Authorization': `Bearer ${accessToken}`,
          'Content-Type': 'application/json'
        }
      });

      alert(`${response.data.nickname}님, 프로필 설정이 완료되었습니다!`);
      onProfileCreated(response.data); // App.js에 완료 알림

    } catch (error) {
      console.error("프로필 저장 실패:", error.response?.data || error);
      
      if (error.response?.data) {
          // 에러 메시지를 예쁘게 보여줌
          const errorData = error.response.data;
          const firstKey = Object.keys(errorData)[0];
          setError(`${firstKey}: ${errorData[firstKey]}`);
      } else {
          setError("프로필 저장 중 오류가 발생했습니다.");
      }
    }
  };

  return (
    <Container className="d-flex justify-content-center align-items-center" style={{ minHeight: '100vh' }}>
      <Card style={{ width: '30rem', padding: '20px' }}>
        <Card.Body>
            <h2 className="text-center mb-4">내 프로필 완성하기</h2>
            <p className="text-muted text-center">소개팅을 시작하기 위해 나머지 정보를 입력해주세요!</p>
            
            {error && <Alert variant="danger">{error}</Alert>}

            <Form onSubmit={handleSubmit}>
                <Form.Group className="mb-3">
                    <Form.Label>닉네임</Form.Label>
                    <Form.Control
                        name="nickname"
                        type="text"
                        placeholder="닉네임 입력"
                        onChange={handleChange}
                        required
                    />
                </Form.Group>

                <Form.Group className="mb-3">
                    <Form.Label>나이</Form.Label>
                    <Form.Control
                        name="age"
                        type="number"
                        placeholder="나이 입력"
                        onChange={handleChange}
                        required
                    />
                </Form.Group>

                <Form.Group className="mb-3">
                    <Form.Label>성별</Form.Label>
                    <Form.Select name="gender" onChange={handleChange} value={formData.gender}>
                        <option value="M">남성</option>
                        <option value="F">여성</option>
                    </Form.Select>
                </Form.Group>

                <Form.Group className="mb-3">
                    <Form.Label>거주 지역</Form.Label>
                    <Form.Control
                        name="location"
                        type="text"
                        placeholder="예: 서울 강남구"
                        onChange={handleChange}
                        required
                    />
                </Form.Group>

                <Form.Group className="mb-3">
                    <Form.Label>관심사</Form.Label>
                    <Form.Control
                        name="interests"
                        type="text"
                        placeholder="예: 영화, 등산, 맛집탐방"
                        onChange={handleChange}
                    />
                </Form.Group>

                <Form.Group className="mb-4">
                    <Form.Label>자기소개</Form.Label>
                    <Form.Control
                        as="textarea"
                        rows={3}
                        name="bio"
                        placeholder="간단한 자기소개를 입력해주세요."
                        onChange={handleChange}
                    />
                </Form.Group>

                <Button variant="primary" type="submit" className="w-100">
                    소개팅 시작하기!
                </Button>
            </Form>
        </Card.Body>
      </Card>
    </Container>
  );
}

export default ProfileForm;
